public int[] mergeSorted(int[] a, int[] b) {
  int[] res = new int[a.length + b.length];
  int i = 0, j = 0, k = 0;
  while (i < a.length && j < b.length) {
    if (a[i] < b[j]) {
      res[k++] = a[i++];
    } else {
      res[k++] = b[j++];
    }
  }
  while (i < a.length) {
    res[k++] = a[i++];
  }
  while (j < b.length) {
    res[k++] = b[j++];
  }
  return res;
}

public int[] rotateLeft(int[] arr) {
  if (arr.length == 0) {
    return arr;
  }
  int first = arr[0];
  for (int i = 0; i < arr.length - 1; i++) {
    arr[i] = arr[i + 1];
  }
  arr[arr.length - 1] = first;
  return arr;
}

public int[] removeDuplicates(int[] arr) {
  if (arr.length == 0) {
    return arr;
  }
  int[] temp = new int[arr.length];
  int j = 0;
  for (int i = 0; i < arr.length - 1; i++) {
    if (arr[i] != arr[i + 1]) {
      temp[j++] = arr[i];
    }
  }
  temp[j++] = arr[arr.length - 1];
  return java.util.Arrays.copyOf(temp, j);
}

